<body>
  <main class="phone">
    <header class="top-bar">
      <div class="brand" aria-label="البنك">
        <span class="brand-mark">ب</span>
        <span>بنكنا</span>
      </div>
      <button class="back-button" type="button" aria-label="رجوع">‹</button>
    </header>

    <section class="content">
      <div class="icon" aria-hidden="true">
        <svg viewBox="0 0 24 24" fill="none">
          <path d="M7 3h10a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z" stroke="currentColor" stroke-width="1.8"/>
          <path d="M9 8h6M9 12h6M9 16h3" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>
        </svg>
      </div>

      <h1>أدخل الرمز</h1>
      <p class="description">
        أرسلنا رمز التحقق المكوّن من 6 أرقام إلى الرقم
        <span class="phone-number">+966 55 123 4567</span>
      </p>

      <form class="otp-form" id="otpForm" novalidate>
        <div class="otp-inputs" id="otpInputs">
          <input type="text" inputmode="numeric" pattern="[0-9]*" maxlength="1" placeholder=" " aria-label="الرمز، الخانة 1" required />
          <input type="text" inputmode="numeric" pattern="[0-9]*" maxlength="1" placeholder=" " aria-label="الرمز، الخانة 2" required />
          <input type="text" inputmode="numeric" pattern="[0-9]*" maxlength="1" placeholder=" " aria-label="الرمز، الخانة 3" required />
          <input type="text" inputmode="numeric" pattern="[0-9]*" maxlength="1" placeholder=" " aria-label="الرمز، الخانة 4" required />
          <input type="text" inputmode="numeric" pattern="[0-9]*" maxlength="1" placeholder=" " aria-label="الرمز، الخانة 5" required />
          <input type="text" inputmode="numeric" pattern="[0-9]*" maxlength="1" placeholder=" " aria-label="الرمز، الخانة 6" required />
        </div>

        <div class="resend">
          <span id="resendText">إعادة الإرسال خلال <strong id="countdown">0:45</strong></span>
        </div>

        <button class="verify-button" id="verifyButton" type="submit">تأكيد</button>
      </form>

      <p class="support">لم يصلك الرمز؟ <a href="tel:920000000">تواصل معنا</a></p>
    </section>
  </main>

  <script>
    const inputs = [...document.querySelectorAll("#otpInputs input")];
    const form = document.getElementById("otpForm");
    const verifyButton = document.getElementById("verifyButton");
    const countdownElement = document.getElementById("countdown");
    const resendText = document.getElementById("resendText");
    let remaining = 45;

    function updateVerifyButton() {
      verifyButton.disabled = inputs.some(input => !input.value);
    }

    inputs.forEach((input, index) => {
      input.addEventListener("input", () => {
        input.value = input.value.replace(/\D/g, "").slice(-1);
        if (input.value && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
        updateVerifyButton();
      });

      input.addEventListener("keydown", event => {
        if (event.key === "Backspace" && !input.value && index > 0) {
          inputs[index - 1].focus();
        }
        if (event.key === "ArrowLeft" && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
        if (event.key === "ArrowRight" && index > 0) {
          inputs[index - 1].focus();
        }
      });

      input.addEventListener("paste", event => {
        const digits = (event.clipboardData.getData("text") || "").replace(/\D/g, "");
        if (digits) {
          event.preventDefault();
          digits.slice(0, 6).split("").forEach((digit, i) => {
            if (inputs[i]) inputs[i].value = digit;
          });
          inputs[Math.min(digits.length, 6) - 1].focus();
          updateVerifyButton();
        }
      });
    });

    const timer = setInterval(() => {
      remaining -= 1;
      const minutes = Math.floor(remaining / 60);
      const seconds = String(remaining % 60).padStart(2, "0");
      countdownElement.textContent = `${minutes}:${seconds}`;

      if (remaining <= 0) {
        clearInterval(timer);
        resendText.innerHTML = '<button type="button" id="resendButton">إعادة إرسال الرمز</button>';
        document.getElementById("resendButton").addEventListener("click", () => {
          remaining = 45;
          countdownElement.textContent = "0:45";
          resendText.innerHTML = 'إعادة الإرسال خلال <strong id="countdown">0:45</strong>';
        });
      }
    }, 1000);

    form.addEventListener("submit", event => {
      event.preventDefault();
      if (!verifyButton.disabled) {
        verifyButton.textContent = "تم التأكيد ✓";
      }
    });

    updateVerifyButton();
  </script>
